story=[];md=[];chapter=''
def clean(s):return str(s).replace('\u2014',' - ').replace('\u2013','-').replace('\u2011','-')
def para(s,style='BodyAudit'):
 story.append(Paragraph(escape(clean(s)).replace('\n','<br/>'),styles[style]));md.append(s+'\n')
def head(s,new=True):
 global chapter
 if new and story:story.append(PageBreak())
 chapter=s;story.append(Paragraph(escape(s),styles['HeadingAudit']));md.append('\n## '+s+'\n')
def sub(s):story.append(Paragraph(escape(s),styles['SubAudit']));md.append('\n### '+s+'\n')
def table(rows,widths=None):
 data=[[Paragraph(escape(clean(c)),styles['SmallAudit']) for c in row] for row in rows]
 t=Table(data,colWidths=widths or [500/len(rows[0])]*len(rows[0]),repeatRows=1,hAlign='LEFT')
 t.setStyle(TableStyle([('BACKGROUND',(0,0),(-1,0),colors.HexColor('#e7eef4')),('VALIGN',(0,0),(-1,-1),'TOP'),('BOTTOMPADDING',(0,0),(-1,-1),8),('TOPPADDING',(0,0),(-1,-1),7),('LINEBELOW',(0,0),(-1,-1),0.35,colors.HexColor('#ced7df'))]))
 story.append(t);story.append(Spacer(1,10));md.append('\n'+'\n'.join(' | '.join(map(str,row)) for row in rows)+'\n')
