def verdict(f):
 t=(f.get('title','')+' '+f.get('detail','')).lower()
 if any(k in t for k in ['invisible to search','rarely rank','cannot receive email','no preview title or image']):return 'Overstated impact; narrow to observed fact (section 8).'
 if f['kind']=='geo':return 'Advisory heuristic; no citation/visibility outcome measured.'
 if f['kind']=='performance':return 'Measured scope matters; inspect browser vs lab vs field provenance.'
 if f['kind']=='security':return 'Passive hygiene observation; no exploit or delivery failure demonstrated.'
 return 'Rule output; review affected page, rendering scope and severity.'
